<body>
    <div class="roll-check-data-container">$1</div>
    <div class="roll-check-card" id="roll-check-card"></div>

<script>
document.addEventListener('DOMContentLoaded', () => {
    const dataContainer = document.querySelector('.roll-check-data-container');
    const card = document.getElementById('roll-check-card');
    if (!dataContainer || !card) return;

    function parseData(text) {
        const data = {};
        const lines = text.trim().split('\n');
        lines.forEach(line => {
            const parts = line.split(/:(.*)/s);
            if (parts.length >= 2) {
                const key = parts[0].trim();
                const value = parts[1].trim();
                const keyMap = {'行动': 'action', '目标点数': 'dc', '掷骰': 'd20', '技能修正': 'skillMod', '装备修正': 'equipMod', '其他修正': 'otherMod', '最终结果': 'total', '判定结果': 'result', '最终伤害': 'finalDamage', '最终治疗': 'finalHeal'};
                if (keyMap[key]) data[keyMap[key]] = value;
            }
        });
        return data;
    }

    function render(data) {
        if (Object.keys(data).length === 0) {
            card.innerHTML = `<div style="padding:10px; text-align:center;">无法解析判定数据</div>`;
            return;
        }

        const { action = '未知行动', dc = 'N/A', d20 = '?', skillMod = '+0', equipMod = '+0', otherMod = '+0', total = '?', result = '未知', finalDamage = '', finalHeal = '' } = data;

        // 构建计算过程 HTML
        let calcHtml = `<span class="roll-item calculation">🎲 ${d20}</span>`;
        [skillMod, equipMod, otherMod].forEach(mod => {
            if (mod && mod !== '+0' && mod !== '0') {
                const match = mod.match(/([+-]?\d+)\s*\((.*)\)/);
                if (match) {
                    calcHtml += `<span class="roll-item calc-mod">${match[1]}<span class="calc-mod-source">(${match[2]})</span></span>`;
                } else {
                     calcHtml += `<span class="roll-item calc-mod">${mod}</span>`;
                }
            }
        });
        calcHtml += `<span class="roll-item calc-mod">=</span> <span class="roll-item calculation calc-total">${total}</span>`;

        // 结果和后续效果
        let resultClass = '';
        switch(result) {
            case '成功': case '标准成功': case '完美成功': resultClass = 'result-success'; break;
            case '失败': resultClass = 'result-failure'; break;
            case '大成功': resultClass = 'result-crit-success'; break;
            case '大失败': resultClass = 'result-crit-failure'; break;
        }

        let consequenceHtml = '';
        if (finalDamage) {
            consequenceHtml = `<span class="arrow">→</span><div class="roll-item consequence"><span style="color: var(--accent-red);">💥 ${finalDamage} 伤害</span></div>`;
        } else if (finalHeal) {
            consequenceHtml = `<span class="arrow">→</span><div class="roll-item consequence"><span style="color: var(--accent-green);">💖 ${finalHeal} 治疗</span></div>`;
        }

        const cardHtml = `
            <div class="roll-check-body">
                <div class="roll-row">
                    <div class="roll-item action">
                        <span class="roll-label">行动:</span>
                        <span class="roll-value">${action}</span>
                    </div>
                    <div class="roll-item dc">
                        <span class="roll-label">目标:</span>
                        <span class="roll-value">🎯 ${dc}</span>
                    </div>
                </div>
                <div class="roll-row">
                    ${calcHtml}
                    <span class="arrow">→</span>
                    <div class="roll-item">
                        <span class="result ${resultClass}">${result}</span>
                    </div>
                    ${consequenceHtml}
                </div>
            </div>
        `;
        card.innerHTML = cardHtml;
    }

    const rawData = dataContainer.textContent.trim().replace(/\[判定开始\]|\[判定结束\]/g, '');
    if (rawData) {
        const parsedData = parseData(rawData);
        render(parsedData);
    }
});
</script>
</body>
</html>
