<script>
    function toggleSection(element) {
        const content = element.nextElementSibling;
        const arrow = element.querySelector('span:last-child');
        if (!content || !arrow) return;
        const isExpanded = content.classList.toggle('expanded');
        element.classList.toggle('expanded-header', isExpanded);
        arrow.textContent = isExpanded ? '[-]' : '[+]';
    }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            const gameData = (messages && messages.length > 0) ? messages[0].data.stat_data : null;
            if (!gameData) { document.getElementById('status-card').innerHTML = "<div class='error-message'>无法加载状态数据。</div>"; return; }

            const _safeGet = (obj, path, def = undefined) => {
                if (!obj || typeof path !== 'string') return def;
                const keys = path.split('.');
                let current = obj;
                for (const key of keys) { if (current === null || current === undefined || !Object.prototype.hasOwnProperty.call(current, key)) return def; current = current[key]; }
                return current;
            };

            const _getFirst = (val, def = 'N/A') => (Array.isArray(val) && val.length > 0) ? String(val[0] ?? def) : def;

            const updateBar = (barId, textId, current, max, color) => {
                const bar = document.getElementById(barId);
                const text = document.getElementById(textId);
                const numCurr = parseFloat(current) || 0;
                const numMax = parseFloat(max) || 100;
                if (text) text.textContent = `${Math.round(numCurr)}/${Math.round(numMax)}`;
                if (bar) {
                    const percent = numMax > 0 ? (numCurr / numMax) * 100 : 0;
                    bar.style.width = `${Math.max(0, Math.min(100, percent))}%`;
                    bar.style.backgroundColor = color;
                }
            };

            const infoHeader = document.getElementById('info-header');
            const playerData = _safeGet(gameData, '玩家信息');
            const worldData = _safeGet(gameData, '世界信息');
            if (playerData || worldData) {
                infoHeader.style.display = 'grid';
                if (playerData) {
                    document.getElementById('player-identity').textContent = _getFirst(playerData.身份);
                    document.getElementById('player-level').textContent = _getFirst(playerData.等级);
                    document.getElementById('player-money').textContent = _getFirst(playerData.持有金钱);
                    updateBar('player-hp-bar', 'player-hp-text', _getFirst(playerData.当前生命值, 0), _getFirst(playerData.最大生命值, 100), 'var(--accent-red)');
                    updateBar('player-exp-bar', 'player-exp-text', _getFirst(playerData.当前经验值, 0), 100, 'var(--accent-blue)');
                }
                if (worldData) {
                    document.getElementById('world-time').textContent = _getFirst(worldData.时间);
                    document.getElementById('world-location').textContent = _getFirst(worldData.地点);
                }
            }

            const createListSection = (containerId, sectionId, data, emoji, title, effectLabel = '效果') => {
                const container = document.getElementById(containerId);
                const section = document.getElementById(sectionId);
                const validKeys = data ? Object.keys(data).filter(k => k !== '$meta' && k !== 'template') : [];
                if (!container || !section || validKeys.length === 0) { if (section) section.style.display = 'none'; return; }
                section.style.display = 'block';
                container.innerHTML = '';
                section.querySelector('.section-header span:first-child').textContent = `${emoji} ${title} (${validKeys.length})`;
                const descLabel = (title === '任务') ? '目标' : '描述';
                for (const key of validKeys) {
                    const value = data[key];
                    if (!Array.isArray(value)) continue;
                    let html = `<div class="property"><span class="property-name">${key}</span>`;
                    if (value[0]) html += `<div class="sub-property"><b>${descLabel}:</b> ${value[0]}</div>`;
                    if (value[1]) html += `<div class="sub-property"><b>${effectLabel}:</b> ${value[1]}</div>`;
                    html += `</div>`;
                    container.innerHTML += html;
                }
            };

            createListSection('tasks-list', 'tasks-section', _safeGet(gameData, '世界信息.任务'), '📜', '任务', '奖励');
            createListSection('equipment-list', 'equipment-section', _safeGet(gameData, '装备'), '🛡️', '装备');
            createListSection('inventory-list', 'inventory-section', _safeGet(gameData, '背包物品'), '📦', '背包');
            createListSection('skills-list', 'skills-section', _safeGet(gameData, '技能'), '🔥', '技能');

            const createTabbedSection = (tabsId, contentId, sectionId, data, emoji, title, type) => {
                const tabsContainer = document.getElementById(tabsId);
                const contentContainer = document.getElementById(contentId);
                const section = document.getElementById(sectionId);
                const validKeys = data ? Object.keys(data).filter(k => k !== '$meta' && k !== 'template') : [];
                if (!tabsContainer || !contentContainer || !section || validKeys.length === 0) { if (section) section.style.display = 'none'; return; }
                section.style.display = 'block';
                tabsContainer.innerHTML = ''; contentContainer.innerHTML = '';
                section.querySelector('.section-header span:first-child').textContent = `${emoji} ${title} (${validKeys.length})`;

                validKeys.forEach((key, index) => {
                    const tabId = `${type}-${index}`;
                    const charData = data[key];
                    if (typeof charData !== 'object' || charData === null) return;
                    const button = document.createElement('button');
                    button.className = 'tab-button';
                    button.textContent = key;
                    tabsContainer.appendChild(button);
                    const contentDiv = document.createElement('div');
                    contentDiv.className = 'tab-content';
                    contentDiv.id = tabId;

                    const longDescProps = ['相貌', '身材', '性格', '外貌'];
                    let html = '';
                    if (type === 'npc') {
                        const props = { '🔰 身份': charData.身份, '🏅 等级': charData.等级, '🎭 相貌': charData.相貌, '🧍 身材': charData.身材, '🧠 性格': charData.性格, '🚶 行为': charData.行为 };
                        for(const propName in props) {
                            const val = _getFirst(props[propName]);
                            if(val !=='N/A') {
                                const alignStart = longDescProps.includes(propName.substring(2)) ? 'data-align-start="true"' : '';
                                html += `<div class="property" ${alignStart}><span class="property-name">${propName}:</span><span class="property-value">${val}</span></div>`;
                            }
                        }
                        const clothing = _getFirst(charData.穿着, '').split('|');
                        if (clothing.length > 0 && clothing[0]) html += `<div class="property"><span class="property-name">🧥 外层:</span><span class="property-value">${clothing[0]}</span></div>`;
                        if (clothing.length > 1 && clothing[1]) html += `<div class="property"><span class="property-name">👙 内衣裤:</span><span class="property-value">${clothing[1]}</span></div>`;
                        if (clothing.length > 2 && clothing[2]) html += `<div class="property"><span class="property-name">👢 鞋袜:</span><span class="property-value">${clothing[2]}</span></div>`;

                        const subLists = {'⚔️ 装备': charData.装备, '⭐ 技能': charData.技能};
                        for(const listName in subLists) {
                            const listData = subLists[listName];
                            const listKeys = listData ? Object.keys(listData).filter(k => k !== '$meta' && k !== 'template') : [];
                            if (listKeys.length > 0) {
                                html += `<div class="property" style="flex-direction:column; align-items:flex-start;"><div class="property-name">${listName}</div>`;
                                for(const itemKey of listKeys) {
                                    const itemValue = listData[itemKey];
                                    if(Array.isArray(itemValue)) {
                                        html += `<div class="sub-property"><b>${itemKey}</b>`;
                                        if (itemValue[0]) html += `<div class="nested-sub-property"><b>描述:</b> ${itemValue[0]}</div>`;
                                        if (itemValue[1]) html += `<div class="nested-sub-property"><b>效果:</b> ${itemValue[1]}</div>`;
                                        html += `</div>`;
                                    }
                                }
                                html += '</div>';
                            }
                        }
                    } else if (type === 'enemy') {
                        const props = { '🏅 等级': charData.等级, '💥 攻击力': charData.攻击力, '👹 外貌': charData.外貌, '🚶 行为': charData.行为 };
                        for(const propName in props) {
                           const val = _getFirst(props[propName]);
                            if(val !=='N/A') {
                                const alignStart = longDescProps.includes(propName.substring(2)) ? 'data-align-start="true"' : '';
                                html += `<div class="property" ${alignStart}><span class="property-name">${propName}:</span><span class="property-value">${val}</span></div>`;
                            }
                        }
                    }

                    const hpTextId = `${tabId}-hp-text`, hpBarId = `${tabId}-hp-bar`;
                    html += `<div class="property progress-display"><span class="property-name" style="flex-shrink:0;">❤️ 生命值:</span><div class="progress-bar-container"><div id="${hpBarId}" class="progress-bar-value"></div></div> <span class="progress-bar-text" id="${hpTextId}"></span></div>`;
                    contentDiv.innerHTML = html;
                    contentContainer.appendChild(contentDiv);
                    updateBar(hpBarId, hpTextId, _getFirst(charData.当前生命值, 0), _getFirst(charData.最大生命值, 100), 'var(--accent-red)');

                    if (index === 0) { button.classList.add('active'); contentDiv.classList.add('active'); }
                    button.addEventListener('click', () => {
                        tabsContainer.querySelectorAll('.tab-button').forEach(btn => btn.classList.remove('active'));
                        contentContainer.querySelectorAll('.tab-content').forEach(c => c.classList.remove('active'));
                        button.classList.add('active');
                        document.getElementById(tabId).classList.add('active');
                    });
                });
            };

            createTabbedSection('npc-tabs', 'npc-content', 'npc-section', _safeGet(gameData, 'NPC信息'), '👥', 'NPC', 'npc');
            createTabbedSection('enemy-tabs', 'enemy-content', 'enemy-section', _safeGet(gameData, '敌人信息'), '👹', '敌人', 'enemy');
        } catch (error) {
            document.getElementById('status-card').innerHTML = `<div class='error-message'>状态栏加载出错: ${error.message}</div>`;
        }
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
</script>
</body>
</html>
